    public double Median(List<int> arr1, List<int> arr2)
    {   
        // Raj Thomas 7th Jun 2026 4:39PM IST 
        int len1 = arr1.Count;
        int len2 = arr2.Count;

        if(len1 > len2) return Median(arr2, arr1);

        // will take arr1 as primary to apply BS 
        int left = 0, right = len1;
        int leftSidePartition = (len1 + len2 + 1) / 2;
        int totalLen = len1 + len2;

        // Binary Search on smaller length Array
        while(left <= right) {
            int l1 = int.MinValue, l2 = int.MinValue;
            int r1 = int.MaxValue, r2 = int.MaxValue;

            int mid1 = left + (right - left)/ 2;
            int mid2 = leftSidePartition - mid1;

            if(mid1 < len1) r1 = arr1[mid1];
            if(mid2 < len2) r2 = arr2[mid2];
            if(mid1 - 1 >= 0) l1 = arr1[mid1 - 1];
            if(mid2 - 1 >= 0) l2 = arr2[mid2 - 1];

            if(l1 <= r2 && l2 <= r1) {
                if(totalLen % 2 == 1) return Math.Max(l1, l2);
                else return (Math.Max(l1, l2) + Math.Min(r1, r2)) / 2.0;
            }
            else if(l1 > r2) {
                right = mid1 - 1;
            }
            else {
                left = mid1 + 1;
            }

        }

        return -1;

    }
}
